import os
import sys

try:
    import sqlite
except ImportError:
    sys.stderr.write('upgrade failed: the Python sqlite module is unavailable\n')
    sys.exit(1)

base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
db_path = os.path.join(base, 'catalog.db')
db = None

try:
    db = sqlite.connect(db_path)
    cursor = db.cursor()

    cursor.execute('SELECT version FROM schema_version')
    versions = cursor.fetchall()
    if len(versions) != 1:
        raise RuntimeError('schema_version must contain exactly one row')

    version = versions[0][0]
    if version == 2:
        cursor.execute('PRAGMA table_info(products)')
        columns = [row[1] for row in cursor.fetchall()]
        if 'price_cents' not in columns:
            raise RuntimeError('schema version is 2 but price_cents is missing')
    elif version == 1:
        cursor.execute('PRAGMA table_info(products)')
        columns = [row[1] for row in cursor.fetchall()]
        if 'price_cents' in columns:
            raise RuntimeError('schema version is 1 but price_cents already exists')

        # PySQLite 1.x starts a transaction on the first write.  SQLite DDL is
        # transactional, so the column and version change commit together.
        cursor.execute('ALTER TABLE products ADD COLUMN price_cents INTEGER NOT NULL DEFAULT 0 CHECK (price_cents >= 0)')
        cursor.execute('UPDATE schema_version SET version = 2 WHERE version = 1')
        if cursor.rowcount != 1:
            raise RuntimeError('schema_version update did not affect one row')
        db.commit()
    else:
        raise RuntimeError('unsupported schema version: %s' % version)
except Exception, error:
    if db is not None:
        try:
            db.rollback()
        except Exception:
            pass
    sys.stderr.write('upgrade failed: %s\n' % error)
    sys.exit(1)
else:
    if db is not None:
        db.close()
